    INSERT INTO "__SCHEMA__".objective_set
      (set_id, version, exam_id, family, section, part, title, payload, item_count, media_required, content_version_id)
    VALUES
    ('telc-deutsch-b1.hv1.01', 'v1', 'telc-deutsch-b1', 'HV1', 'HV', 1, 'Nachrichten von Freunden', '{"title":"Nachrichten von Freunden","items":[{"n":41,"statement":"Anna kann am Freitag nicht ins Kino gehen, weil sie länger arbeiten muss."},{"n":42,"statement":"Ben sagt das Fußballtreffen am Samstag ab, weil er arbeiten muss."},{"n":43,"statement":"Lisa wartet zehn Minuten am Eingang des Restaurants und fährt dann nach Hause."},{"n":44,"statement":"Peter bittet darum, mit dem Auto abgeholt zu werden, weil sein Fahrrad kaputt ist."},{"n":45,"statement":"Familie Kaya reserviert einen Tisch für vier Personen."}]}'::jsonb, 5, true, 'telc-deutsch-b1.hv1.01@v1'),
    ('telc-deutsch-b1.hv1.02', 'v1', 'telc-deutsch-b1', 'HV1', 'HV', 1, 'Ansagen und Nachrichten zum Thema Reisen', '{"title":"Ansagen und Nachrichten zum Thema Reisen","items":[{"n":41,"statement":"Jonas hat Verspätung und schafft es nicht mehr zum Mittagessen."},{"n":42,"statement":"Der Zug nach München fährt heute von Gleis acht."},{"n":43,"statement":"Sofias Flug nach Lissabon wurde gestrichen, sie fliegt jetzt morgen früh."},{"n":44,"statement":"Das Frühstück im Hotel Sonne kostet extra."},{"n":45,"statement":"Die reservierten Fahrräder müssen bis achtzehn Uhr abgeholt werden."}]}'::jsonb, 5, true, 'telc-deutsch-b1.hv1.02@v1'),
    ('telc-deutsch-b1.hv1.03', 'v1', 'telc-deutsch-b1', 'HV1', 'HV', 1, 'Nachrichten rund um Gesundheit und Termine', '{"title":"Nachrichten rund um Gesundheit und Termine","items":[{"n":41,"statement":"Der Termin bei Dr. Noll am Mittwoch wird verschoben, die Praxis bietet Donnerstag oder Freitag an."},{"n":42,"statement":"Laura bringt ihrem Vater morgen die neuen Rezepte mit."},{"n":43,"statement":"Der Kurs am Dienstag findet wie geplant statt."},{"n":44,"statement":"Die Apotheke hat alle bestellten Medikamente vorrätig."},{"n":45,"statement":"Der Kontrolltermin beim Zahnarzt ist am Freitag um elf Uhr."}]}'::jsonb, 5, true, 'telc-deutsch-b1.hv1.03@v1'),
    ('telc-deutsch-b1.hv2.01', 'v1', 'telc-deutsch-b1', 'HV2', 'HV', 2, 'Interview mit der Ernährungsberaterin Dr. Karin Baum', '{"title":"Interview mit der Ernährungsberaterin Dr. Karin Baum","items":[{"n":46,"statement":"Frau Baum empfiehlt, sofort mit einer strengen Diät zu beginnen."},{"n":47,"statement":"Ihrer Erfahrung nach halten strenge Diäten meistens nur zwei oder drei Wochen."},{"n":48,"statement":"Gesundes Essen ist laut Frau Baum immer teurer als Fast Food."},{"n":49,"statement":"Spezielle Riegel und Säfte in bunten Packungen hält sie für überflüssig."},{"n":50,"statement":"In der Praxis sehen sie immer mehr zehnjährige Kinder mit Übergewicht."},{"n":51,"statement":"Frau Baum findet alle Ernährungsvideos im Internet gefährlich."},{"n":52,"statement":"Sie empfiehlt, bei Fragen zu Medikamenten eine Ärztin oder einen Arzt zu fragen."},{"n":53,"statement":"Ein Firmenkurs dauert acht Wochen mit einem Termin pro Woche."},{"n":54,"statement":"In den Firmenkursen müssen alle Teilnehmer mitkochen, auch wenn sie nicht wollen."},{"n":55,"statement":"Kleine Firmen mit weniger als zwanzig Mitarbeitern zahlen 600 Euro für den ganzen Kurs."}]}'::jsonb, 10, true, 'telc-deutsch-b1.hv2.01@v1'),
    ('telc-deutsch-b1.hv2.02', 'v1', 'telc-deutsch-b1', 'HV2', 'HV', 2, 'Interview mit dem Fahrlehrer Thomas Reinhardt', '{"title":"Interview mit dem Fahrlehrer Thomas Reinhardt","items":[{"n":46,"statement":"Herr Reinhardt sagt, dass junge Fahrschüler heute unsicherer sind als früher."},{"n":47,"statement":"Viele Fahrschüler haben schon als Kinder viel über Autos gelernt, weil ihre Familien ein Auto haben."},{"n":48,"statement":"Vor zwanzig Jahren war der Führerschein meist billiger als heute."},{"n":49,"statement":"Wer die Theorieprüfung früh besteht, braucht meistens weniger Fahrstunden."},{"n":50,"statement":"Beim begleiteten Fahren reicht es, wenn die Begleitperson einen Führerschein hat."},{"n":51,"statement":"Die Begleitperson muss mindestens dreißig Jahre alt sein."},{"n":52,"statement":"Für die Fahrschule sind E-Autos im Unterricht völlig unproblematisch."},{"n":53,"statement":"Herr Reinhardt erwartet, dass in zehn Jahren fast alle Fahrschulen E-Autos nutzen."},{"n":54,"statement":"Er sagt, dass man das Fahren in zwei Wochen lernen kann."},{"n":55,"statement":"Er möchte, dass Fahrschüler die Regeln lernen, weil sie im Verkehr wichtig sind."}]}'::jsonb, 10, true, 'telc-deutsch-b1.hv2.02@v1'),
    ('telc-deutsch-b1.hv2.03', 'v1', 'telc-deutsch-b1', 'HV2', 'HV', 2, 'Interview mit der Umweltberaterin Julia Kessler', '{"title":"Interview mit der Umweltberaterin Julia Kessler","items":[{"n":46,"statement":"In Deutschland produziert jeder Mensch im Durchschnitt etwa 620 Kilogramm Haushaltsabfall pro Jahr."},{"n":47,"statement":"Frau Kessler findet, dass Recycling allein ausreicht."},{"n":48,"statement":"Joghurtbecher sollte man kurz ausspülen, bevor man sie in den gelben Sack wirft."},{"n":49,"statement":"Benutzte Taschentücher gehören ins Altpapier."},{"n":50,"statement":"Blaue Glasflaschen gehören meistens zum grünen Glas."},{"n":51,"statement":"Alle Gastronomiebetriebe in Deutschland müssen seit 2023 Mehrweg anbieten."},{"n":52,"statement":"Studien zufolge sind Mehrwegbecher ab etwa zwanzig Nutzungen besser als Einwegbecher."},{"n":53,"statement":"Man muss den Mehrwegbecher in demselben Café zurückgeben, in dem man ihn gekauft hat."},{"n":54,"statement":"Frau Kessler empfiehlt, Geräte reparieren zu lassen statt neue zu kaufen."},{"n":55,"statement":"Die Gemeinde in Bayern hat mit den Tipps 30 Prozent mehr Restmüll produziert."}]}'::jsonb, 10, true, 'telc-deutsch-b1.hv2.03@v1'),
    ('telc-deutsch-b1.hv3.01', 'v1', 'telc-deutsch-b1', 'HV3', 'HV', 3, 'Ansagen und Nachrichten aus Geschäften und Einrichtungen', '{"title":"Ansagen und Nachrichten aus Geschäften und Einrichtungen","items":[{"n":56,"statement":"Die Torte kann man am Freitag zwischen acht und sechzehn Uhr abholen."},{"n":57,"statement":"Der Supermarkt schließt heute schon um neunzehn Uhr."},{"n":58,"statement":"Das Sofa wird am Dienstag zwischen dreizehn und siebzehn Uhr geliefert."},{"n":59,"statement":"Die Straßenbahnlinie 4 fährt heute nur bis zur Haltestelle Marktplatz."},{"n":60,"statement":"Das bestellte Buch kann man bis Montag abholen."}]}'::jsonb, 5, true, 'telc-deutsch-b1.hv3.01@v1'),
    ('telc-deutsch-b1.hv3.02', 'v1', 'telc-deutsch-b1', 'HV3', 'HV', 3, 'Durchsagen und Nachrichten für Reisende', '{"title":"Durchsagen und Nachrichten für Reisende","items":[{"n":56,"statement":"Der Regionalexpress nach Stuttgart fährt heute von Gleis zwölf."},{"n":57,"statement":"Der Flug nach Rom startet jetzt um sechzehn Uhr fünfzig am Gate B 12."},{"n":58,"statement":"Für den Urlaub in Griechenland muss der Reisepass noch mindestens sechs Monate gültig sein."},{"n":59,"statement":"Die S-Bahn fährt heute über die Station Universität."},{"n":60,"statement":"In der Jugendherberge kostet das Abendessen neun Euro pro Person."}]}'::jsonb, 5, true, 'telc-deutsch-b1.hv3.02@v1'),
    ('telc-deutsch-b1.hv3.03', 'v1', 'telc-deutsch-b1', 'HV3', 'HV', 3, 'Nachrichten aus Verein, Schule und Musikschule', '{"title":"Nachrichten aus Verein, Schule und Musikschule","items":[{"n":56,"statement":"Das Training der Jugendmannschaft findet am Mittwoch in der Halle statt."},{"n":57,"statement":"Die Jahreshauptversammlung ist am 14. März um neunzehn Uhr."},{"n":58,"statement":"Der Gitarrenkurs am Donnerstag findet wie geplant statt."},{"n":59,"statement":"Der Elternabend der Klasse 4b beginnt um neunzehn Uhr dreißig in Raum 204."},{"n":60,"statement":"Der Lesekurs für Erwachsene kostet 25 Euro und dauert sechs Wochen."}]}'::jsonb, 5, true, 'telc-deutsch-b1.hv3.03@v1'),
    ('telc-deutsch-b1.lv1.01', 'v1', 'telc-deutsch-b1', 'LV1', 'LV', 1, 'Wohnungen und WG-Zimmer', '{"title":"Wohnungen und WG-Zimmer","headlines":[{"id":"a","text":"Ferienhaus an der Ostsee zu vermieten"},{"id":"b","text":"Zimmer in einer Wohngemeinschaft für Nichtraucher"},{"id":"c","text":"4-Zimmer-Wohnung mit Garten für eine Familie gesucht"},{"id":"d","text":"Möbliertes Zimmer für Studenten in Uninähe"},{"id":"e","text":"Bürofläche im Gewerbegebiet zu vermieten"},{"id":"f","text":"Nachmieter für eine 1-Zimmer-Wohnung im Zentrum"},{"id":"g","text":"Ebenerdige Wohnung mit Balkon für eine Seniorin gesucht"},{"id":"h","text":"Tauschwohnung: zwei Zimmer gegen drei Zimmer"},{"id":"i","text":"Wohnung mit Werkstatt für Handwerker"},{"id":"j","text":"Zwei ältere Damen suchen eine ruhige Mitbewohnerin"}],"texts":[{"id":"1","text":"Wir sind zwei Studentinnen und suchen ab 1. Mai eine dritte Mitbewohnerin für unsere Wohnung. Das Zimmer ist 18 Quadratmeter groß und kostet 380 Euro warm, Internet ist inklusive. Wichtig ist uns, dass du ruhig bist und nicht rauchst."},{"id":"2","text":"Wir sind eine Familie mit zwei kleinen Kindern und suchen dringend eine größere Wohnung. Sie sollte vier Zimmer haben und möglichst einen Garten. Ein Kindergarten in der Nähe wäre für uns sehr wichtig."},{"id":"3","text":"Nachmieter gesucht! Kleine Wohnung mit einem Zimmer im dritten Stock, 32 Quadratmeter, direkt im Zentrum. Einen Aufzug gibt es leider nicht. Wir vermieten nur an Berufstätige."},{"id":"4","text":"Ich bin 68 Jahre alt und suche eine Wohnung im Erdgeschoss. Ein Balkon ist mir sehr wichtig, denn ich habe viele Blumen. Treppen kann ich nämlich nicht mehr gut steigen."},{"id":"5","text":"Ich studiere im ersten Semester und suche ein möbliertes Zimmer für ein halbes Jahr. Am besten wäre eine Wohnung ganz in der Nähe der Universität, denn ich habe kein Auto."}]}'::jsonb, 5, false, 'telc-deutsch-b1.lv1.01@v1'),
    ('telc-deutsch-b1.lv1.02', 'v1', 'telc-deutsch-b1', 'LV1', 'LV', 1, 'Stellenanzeigen und Arbeitsuche', '{"title":"Stellenanzeigen und Arbeitsuche","headlines":[{"id":"a","text":"Aushilfe für das Café am Wochenende gesucht"},{"id":"b","text":"Praktikumsplatz im Marketing"},{"id":"c","text":"Lagerarbeiter mit Führerschein für die Frühschicht"},{"id":"d","text":"Teilzeitstelle für eine Krankenschwester gesucht"},{"id":"e","text":"Deutschlehrer für Abendkurse gesucht"},{"id":"f","text":"Reinigungskraft für Bürogebäude"},{"id":"g","text":"Ausbildung zum Koch/zur Köchin"},{"id":"h","text":"Verkäuferin für eine Bäckerei"},{"id":"i","text":"IT-Spezialist für die Arbeit von zu Hause"},{"id":"j","text":"Nachhilfe in Mathematik für Schüler"}],"texts":[{"id":"1","text":"Unser kleines Café in der Innenstadt sucht eine Aushilfe. Sie arbeiten nur am Samstag und am Sonntag von acht bis vierzehn Uhr. Wir erwarten Freundlichkeit und etwas Erfahrung mit Kaffee."},{"id":"2","text":"Du studierst Wirtschaft und möchtest drei Monate praktische Erfahrung sammeln? Unsere Firma bietet ab September ein Praktikum im Marketing an. Bewerbungen bitte per E-Mail."},{"id":"3","text":"Für unser Lager suchen wir einen Mitarbeiter. Die Arbeit beginnt früh um sechs Uhr, deshalb brauchst du einen Führerschein. Die Stelle ist Vollzeit."},{"id":"4","text":"Ich bin gelernte Krankenschwester und habe zwei kleine Kinder. Deshalb suche ich eine Stelle mit etwa zwanzig Stunden pro Woche. Nachmittags kann ich leider nicht arbeiten."},{"id":"5","text":"Unsere Sprachschule braucht dringend eine Lehrkraft für Deutsch als Fremdsprache. Der Kurs findet zweimal pro Woche abends statt. Sie sollten Muttersprachler sein."}]}'::jsonb, 5, false, 'telc-deutsch-b1.lv1.02@v1'),
    ('telc-deutsch-b1.lv1.03', 'v1', 'telc-deutsch-b1', 'LV1', 'LV', 1, 'Kurse und Freizeitangebote', '{"title":"Kurse und Freizeitangebote","headlines":[{"id":"a","text":"Yoga für Anfänger am Abend"},{"id":"b","text":"Computerkenntnisse für ältere Menschen"},{"id":"c","text":"Schwimmen lernen für Kinder"},{"id":"d","text":"Fotografieren lernen in der Stadt"},{"id":"e","text":"Abendkurs Deutsch B1 mit Prüfungsvorbereitung"},{"id":"f","text":"Gitarrenunterricht für Erwachsene"},{"id":"g","text":"Tanzkurs für Paare"},{"id":"h","text":"Kochkurs: Italienische Küche"},{"id":"i","text":"Theoriekurs für den Führerschein"},{"id":"j","text":"Nähen für Fortgeschrittene"}],"texts":[{"id":"1","text":"Du hast noch nie Yoga gemacht? Kein Problem! Unser Kurs am Dienstagabend um achtzehn Uhr ist genau für Anfänger gedacht. Zehn Termine kosten achtzig Euro, eine Matte bringst du bitte selbst mit."},{"id":"2","text":"In diesem Kurs lernen Seniorinnen und Senioren, wie man E-Mails schreibt und im Internet einkauft. Vorkenntnisse sind nicht nötig, wir üben alles ganz langsam."},{"id":"3","text":"Ab fünf Jahren können Kinder bei uns das Schwimmen lernen. Der Kurs findet jeden Samstag im Hallenbad statt. Die Anmeldung ist nur online möglich."},{"id":"4","text":"Beim Fotokurs am Wochenende treffen wir uns draußen und fotografieren die Stadt. Du brauchst eine eigene Kamera und bequeme Schuhe, denn wir laufen viel."},{"id":"5","text":"Unser Deutschkurs auf dem Niveau B1 findet dreimal pro Woche abends statt. Wir üben gezielt für die Prüfung, damit du sicher bestehen kannst."}]}'::jsonb, 5, false, 'telc-deutsch-b1.lv1.03@v1'),
    ('telc-deutsch-b1.lv2.01', 'v1', 'telc-deutsch-b1', 'LV2', 'LV', 2, 'Mehr Platz für Fahrräder in der Innenstadt', '{"title":"Mehr Platz für Fahrräder in der Innenstadt","text":"Die Stadt Freiburg will den Verkehr in der Innenstadt neu ordnen. Ab dem nächsten Frühjahr sollen Autofahrerinnen und Autofahrer einige Straßen nicht mehr benutzen dürfen. Stattdessen entstehen dort breite Radwege und zusätzliche Abstellplätze für Fahrräder.\n\nNach Angaben der Stadtverwaltung fahren täglich etwa 25.000 Menschen mit dem Rad zur Arbeit oder zur Schule. In den letzten fünf Jahren ist diese Zahl um fast die Hälfte gestiegen. Gleichzeitig gab es immer mehr Unfälle zwischen Autos und Fahrrädern, besonders an Kreuzungen. Mit den neuen Wegen hofft man, diese Unfälle zu reduzieren.\n\nNicht alle sind mit den Plänen zufrieden. Die Geschäftsleute in der Innenstadt befürchten, dass ihre Kunden nicht mehr mit dem Auto kommen und deshalb weniger einkaufen. „Viele ältere Menschen können nicht Rad fahren und brauchen das Auto“, sagt der Sprecher des Handelsverbands. Die Stadt antwortet, dass die Parkhäuser am Rand der Innenstadt erhalten bleiben und dass ein kostenloser Bus alle zehn Minuten fährt.\n\nDie Bauarbeiten beginnen im März und sollen ein Jahr dauern. Während dieser Zeit kann es an manchen Tagen zu Staus kommen. Die Stadt bittet die Bürgerinnen und Bürger, in dieser Zeit häufiger öffentliche Verkehrsmittel zu nutzen. Informationen gibt es im Internet und in einem Büro in der Rathausstraße, das montags bis freitags von neun bis siebzehn Uhr geöffnet ist.","questions":[{"n":6,"question":"Was soll sich in der Innenstadt ändern?","options":{"a":"Autos dürfen dort bald überall fahren.","b":"In einigen Straßen sollen Radwege entstehen.","c":"Der Busverkehr wird ganz eingestellt."}},{"n":7,"question":"Wie hat sich die Zahl der Radfahrer entwickelt?","options":{"a":"Sie ist in fünf Jahren um fast die Hälfte gestiegen.","b":"Sie ist in den letzten Jahren leicht gesunken.","c":"Sie ist gleich geblieben."}},{"n":8,"question":"Warum gibt es Kritik an den Plänen?","options":{"a":"Die Geschäftsleute befürchten weniger Kunden.","b":"Die Radfahrer wollen breitere Wege.","c":"Die Bauarbeiten sind zu teuer."}},{"n":9,"question":"Was bietet die Stadt als Lösung an?","options":{"a":"kostenlose Fahrräder für alle","b":"Parkhäuser am Rand und einen kostenlosen Bus","c":"billigere Taxis in der Innenstadt"}},{"n":10,"question":"Was passiert während der Bauarbeiten?","options":{"a":"Es kann an manchen Tagen zu Staus kommen.","b":"Die Innenstadt ist ein Jahr lang ganz gesperrt.","c":"Der Bus fährt nur am Wochenende."}}]}'::jsonb, 5, false, 'telc-deutsch-b1.lv2.01@v1'),
    ('telc-deutsch-b1.lv2.02', 'v1', 'telc-deutsch-b1', 'LV2', 'LV', 2, 'Gesünder arbeiten im Büro', '{"title":"Gesünder arbeiten im Büro","text":"Viele Menschen sitzen heute mehr als acht Stunden am Tag. Ärzte warnen seit Jahren, dass langes Sitzen Rückenschmerzen, Kopfschmerzen und sogar Herzprobleme verursachen kann. Deshalb starten immer mehr Firmen Programme für die Gesundheit ihrer Mitarbeiter.\n\nDie Firma Meier und Söhne in Hannover hat vor zwei Jahren damit begonnen, höhenverstellbare Tische zu kaufen. Die Beschäftigten können nun im Stehen arbeiten, wann immer sie wollen. Außerdem gibt es jeden Dienstag und Donnerstag um halb zwölf eine gemeinsame Bewegungspause von fünfzehn Minuten. Eine Physiotherapeutin zeigt dabei einfache Übungen für Nacken und Rücken.\n\nDie Ergebnisse sind positiv. Nach Angaben der Personalabteilung sind die Fehltage im letzten Jahr um zwanzig Prozent gesunken. Auch die Mitarbeiter sind zufriedener: In einer Umfrage gaben achtzig Prozent an, dass sie sich nach der Arbeit weniger müde fühlen. Kritik gibt es trotzdem. Einige Beschäftigte sagen, dass die Bewegungspause mitten in der Arbeitszeit liegt und sie danach länger bleiben müssen.\n\nDie Krankenkasse AOK empfiehlt kleinen Betrieben, mit einfachen Mitteln anzufangen. Schon ein kurzer Spaziergang in der Mittagspause oder Treppensteigen statt Aufzug hilft. Wichtig sei, dass die Chefs selbst mitmachen, denn dann fühlen sich die Mitarbeiter nicht kontrolliert. Die Krankenkasse bietet kostenlose Beratung per Telefon und im Internet an.","questions":[{"n":6,"question":"Warum starten immer mehr Firmen Gesundheitsprogramme?","options":{"a":"Weil langes Sitzen krank machen kann.","b":"Weil die Möbel billiger geworden sind.","c":"Weil die Mitarbeiter mehr Geld verlangen."}},{"n":7,"question":"Was hat die Firma in Hannover gemacht?","options":{"a":"Sie hat höhenverstellbare Tische gekauft.","b":"Sie hat die Arbeitszeit verkürzt.","c":"Sie hat ein Fitnessstudio gebaut."}},{"n":8,"question":"Was zeigen die Ergebnisse in der Firma?","options":{"a":"Die Fehltage sind um zwanzig Prozent gesunken.","b":"Die Mitarbeiter arbeiten deutlich länger.","c":"Die Firma hat weniger Kunden."}},{"n":9,"question":"Was kritisieren einige Mitarbeiter?","options":{"a":"Die Übungen sind zu schwer.","b":"Die Pause liegt in der Arbeitszeit, deshalb bleiben sie länger.","c":"Die Therapeutin kommt zu selten."}},{"n":10,"question":"Was empfiehlt die Krankenkasse kleinen Betrieben?","options":{"a":"sofort teure Geräte zu kaufen","b":"mit einfachen Mitteln anzufangen und dass die Chefs mitmachen","c":"die Mittagspause abzuschaffen"}}]}'::jsonb, 5, false, 'telc-deutsch-b1.lv2.02@v1'),
    ('telc-deutsch-b1.lv2.03', 'v1', 'telc-deutsch-b1', 'LV2', 'LV', 2, 'Mit dem Zug in den Urlaub: neue Angebote der Bahn', '{"title":"Mit dem Zug in den Urlaub: neue Angebote der Bahn","text":"Wer in diesem Sommer mit dem Zug in den Urlaub fahren möchte, hat mehr Auswahl als je zuvor. Die Deutsche Bahn hat angekündigt, ab Juni zusätzliche Züge an die Nordsee und in die Alpen einzusetzen. Besonders am Freitagnachmittag und am Sonntagabend waren die Züge in den letzten Jahren oft voll.\n\nNeu ist auch ein Angebot für Familien: Kinder unter sechzehn Jahren fahren in den Sommerferien kostenlos, wenn mindestens ein Elternteil ein Ticket kauft. Wer sein Ticket vier Wochen vor der Reise bucht, bekommt außerdem einen Rabatt von dreißig Prozent. Die Bahn empfiehlt, Sitzplätze rechtzeitig zu reservieren, besonders für lange Strecken.\n\nReisende mit viel Gepäck können ihren Koffer jetzt schon am Abend vor der Reise an ausgewählten Bahnhöfen abgeben. Der Koffer wird dann direkt zum Zielbahnhof gebracht. Dieser Service kostet zwölf Euro pro Gepäckstück und ist bisher nur auf sechs Strecken möglich.\n\nDer Fahrgastverband begrüßt die neuen Angebote, kritisiert aber die Preise. „Für eine Familie mit zwei Kindern ist die Bahn immer noch teurer als das Auto“, sagt eine Sprecherin. Die Bahn antwortet, dass man mit dem neuen Familienangebot und dem Frühbucherrabatt bis zu vierzig Prozent sparen könne. Wer sich informieren möchte, findet alle Details auf der Internetseite der Bahn oder in den Reisezentren, die montags bis freitags von acht bis achtzehn Uhr geöffnet sind.","questions":[{"n":6,"question":"Was plant die Deutsche Bahn ab Juni?","options":{"a":"zusätzliche Züge an die Nordsee und in die Alpen","b":"billigere Fahrkarten für Autofahrer","c":"weniger Züge am Wochenende"}},{"n":7,"question":"Was gilt in den Sommerferien für Familien?","options":{"a":"Kinder unter sechzehn Jahren fahren kostenlos.","b":"Alle Tickets für die ganze Familie sind gratis.","c":"Kinder zahlen die Hälfte des Preises."}},{"n":8,"question":"Wie bekommt man einen Rabatt von dreißig Prozent?","options":{"a":"wenn man vier Wochen vor der Reise bucht","b":"wenn man an einem Sonntag fährt","c":"wenn man im Reisezentrum bezahlt"}},{"n":9,"question":"Was ist der neue Gepäckservice?","options":{"a":"Man kann den Koffer am Abend vor der Reise abgeben.","b":"Man darf nur noch einen Koffer mitnehmen.","c":"Das Gepäck wird kostenlos transportiert."}},{"n":10,"question":"Was kritisiert der Fahrgastverband?","options":{"a":"die Preise für Familien","b":"die langen Fahrzeiten","c":"die wenigen Sitzplätze"}}]}'::jsonb, 5, false, 'telc-deutsch-b1.lv2.03@v1'),
    ('telc-deutsch-b1.lv3.01', 'v1', 'telc-deutsch-b1', 'LV3', 'LV', 3, 'LV3 1', '{"ads":[{"id":"a","text":"Möbeltransport und Umzugshilfe: Zwei starke Männer mit Transporter. Ab 60 Euro pro Stunde, auch am Wochenende. Tel. 0221 55 44 33."},{"id":"b","text":"Wir reinigen Teppiche und Sofas direkt bei Ihnen zu Hause. Trocknung in zwei Stunden, umweltfreundliche Mittel. Termine nach Absprache."},{"id":"c","text":"Gebrauchte Küchen zu kaufen: Über 40 Küchen im Lager. Lieferung und Aufbau inklusive. Öffnungszeiten: Mittwoch bis Samstag 10–18 Uhr."},{"id":"d","text":"Schreinerei Krause: Wir bauen Einbauschränke nach Maß und reparieren Türen und Fenster. Kostenlose Beratung vor Ort."},{"id":"e","text":"Sie möchten Ihre Wohnung vermieten? Wir übernehmen die Verwaltung, suchen Mieter und kümmern uns um alle Fragen. Faire Preise für Eigentümer."},{"id":"f","text":"Gartenpflege: Rasen mähen, Hecken schneiden, Blumen pflanzen. Auch regelmäßige Betreuung möglich. Tel. 0176 22 33 44."},{"id":"g","text":"Elektriker-Notdienst rund um die Uhr: Wenn der Strom ausfällt, sind wir in 45 Minuten bei Ihnen. Festpreis 90 Euro."},{"id":"h","text":"Malerbetrieb Weiß: Streichen von Wohnungen und Treppenhäusern. Wir arbeiten sauber und schnell, das Angebot ist kostenlos."},{"id":"i","text":"Second-Hand-Laden für Kleidung und Hausrat: Wir nehmen gut erhaltene Sachen kostenlos an und verkaufen sie für einen guten Zweck."},{"id":"j","text":"Fahrradwerkstatt: Reparatur und Service für alle Marken. Neuer Standort in der Gartenstraße 12. Termin online buchen."},{"id":"k","text":"Nachhilfe für Kinder in Mathematik und Deutsch, Klasse 1 bis 6, bei Ihnen zu Hause. 18 Euro pro Stunde."},{"id":"l","text":"Fahrschule Sonne: Neue Kurse für Theorie und Praxis, auch Intensivkurse in den Ferien. Anmeldung persönlich oder telefonisch."}],"situations":[{"n":11,"text":"Sie ziehen in eine andere Wohnung und brauchen Hilfe, weil Ihre Waschmaschine und das Sofa zu schwer sind."},{"n":12,"text":"Ihr Sofa ist schmutzig, und Sie möchten es reinigen lassen, ohne es wegzubringen."},{"n":13,"text":"In Ihrer Wohnung ist abends plötzlich kein Strom mehr, und Sie brauchen sofort Hilfe."},{"n":14,"text":"Sie möchten Ihre Wohnung neu streichen lassen und wünschen vorher ein Angebot."},{"n":15,"text":"Ihre Wohnungstür schließt nicht mehr richtig, und Sie suchen jemanden, der sie repariert."},{"n":16,"text":"Sie haben gut erhaltene Kleidung und möchten sie spenden."},{"n":17,"text":"Sie fahren in den Urlaub und suchen jemanden, der sich in dieser Zeit um Ihren Garten kümmert."},{"n":18,"text":"Sie besitzen eine Wohnung und möchten sie vermieten, haben aber keine Zeit für die Verwaltung."},{"n":19,"text":"Sie suchen für die Wintermonate eine günstige Ferienwohnung am Meer für zwei Wochen."},{"n":20,"text":"Ihr Computer startet nicht mehr, und Sie suchen eine Werkstatt, die ihn repariert."}]}'::jsonb, 10, false, 'telc-deutsch-b1.lv3.01@v1'),
    ('telc-deutsch-b1.lv3.02', 'v1', 'telc-deutsch-b1', 'LV3', 'LV', 3, 'LV3 2', '{"ads":[{"id":"a","text":"Zahnarztpraxis Dr. Berger: Wir behandeln auch Angstpatienten und bieten Termine am Samstagvormittag an. Tel. 030 44 55 66."},{"id":"b","text":"Physiotherapie am Park: Massage, Krankengymnastik und Training nach Verletzungen. Rezept vom Arzt nötig, Termin nur nach Vereinbarung."},{"id":"c","text":"Apotheke am Markt: Wir liefern Medikamente kostenlos nach Hause, Bestellung bis 16 Uhr per Telefon oder App."},{"id":"d","text":"Fitnessstudio Aktiv: Probetraining kostenlos. Kurse von Yoga bis Boxen, geöffnet täglich 6–23 Uhr. Monatlich ab 29 Euro."},{"id":"e","text":"Optiker Schmitt: Brillen in einer Stunde, auch Gleitsichtbrillen. Kostenlose Sehtests ohne Termin."},{"id":"f","text":"Ernährungsberatung für Familien: Wir erstellen Essenspläne und begleiten Sie acht Wochen. Auch online möglich."},{"id":"g","text":"Psychologische Beratung in Krisen: Telefonisch rund um die Uhr, anonym und kostenlos. 0800 111 0 222."},{"id":"h","text":"Hörgeräte-Zentrum: Kostenloser Hörtest und Beratung, auch Hausbesuche für ältere Menschen."},{"id":"i","text":"Schwimmbad Therme Süd: Sauna, Dampfbad und Whirlpool. Dienstags Seniorenrabatt 30 Prozent."},{"id":"j","text":"Pflegedienst Herz: Wir helfen zu Hause bei der Körperpflege und beim Anziehen. Auch am Wochenende."},{"id":"k","text":"Sanitätshaus: Rollstühle, Gehhilfen und Bandagen zum Ausleihen oder Kaufen. Beratung zu Hause möglich."},{"id":"l","text":"Krankenfahrten: Wir bringen Sie zu Untersuchungen und wieder nach Hause, auch mit Rollstuhl. Feste Preise, Termine telefonisch."}],"situations":[{"n":11,"text":"Sie haben starke Rückenschmerzen, und der Arzt hat Ihnen Krankengymnastik verschrieben."},{"n":12,"text":"Sie können Ihre Medikamente nicht selbst abholen und möchten sie nach Hause bekommen."},{"n":13,"text":"Ihre Mutter ist 84 und kann nicht mehr allein zum Arzt gehen. Sie suchen einen Fahrdienst."},{"n":14,"text":"Sie hören schlecht und möchten zuerst kostenlos testen lassen, ob ein Hörgerät nötig ist."},{"n":15,"text":"Sie haben seit Wochen keine Kraft und möchten mit jemandem über Ihre Probleme sprechen, ohne dass es jemand erfährt."},{"n":16,"text":"Sie möchten sich gesünder ernähren und brauchen einen Essensplan für die ganze Familie."},{"n":17,"text":"Ihre neue Brille ist fertig, und Sie möchten sie noch heute abholen."},{"n":18,"text":"Ihr Vater braucht nach einer Operation Hilfe beim Waschen zu Hause."},{"n":19,"text":"Sie suchen ein neues Auto für Ihre Familie und möchten verschiedene Modelle probefahren."},{"n":20,"text":"Ihre Küche ist alt, und Sie möchten eine neue einbauen lassen."}]}'::jsonb, 10, false, 'telc-deutsch-b1.lv3.02@v1'),
    ('telc-deutsch-b1.lv3.03', 'v1', 'telc-deutsch-b1', 'LV3', 'LV', 3, 'LV3 3', '{"ads":[{"id":"a","text":"Busreisen Meier: Tagesfahrten nach Amsterdam, Prag und Wien. Abfahrt immer samstags um 7 Uhr, Preis inklusive Mittagessen."},{"id":"b","text":"Flughafentransfer: Wir holen Sie zu Hause ab und bringen Sie pünktlich zum Flug. Festpreis, auch nachts."},{"id":"c","text":"Fahrradverleih am See: Räder für Erwachsene und Kinder, Helme gratis. Täglich 9–19 Uhr, halber Tag 8 Euro."},{"id":"d","text":"Sprachreisen für Jugendliche: Drei Wochen England mit Gastfamilie und Unterricht. Betreuung rund um die Uhr."},{"id":"e","text":"Fernbus Linie Nord: Täglich Berlin–Hamburg ab 9 Euro, Steckdosen und WLAN an Bord."},{"id":"f","text":"Reisebüro Sonnenschein: Wir planen Ihre Fernreise und kümmern uns um Visa und Versicherungen."},{"id":"g","text":"Autovermietung Blitz: Kleinwagen ab 25 Euro pro Tag, Kilometer unbegrenzt, Abholung am Bahnhof."},{"id":"h","text":"Wohnmobil zu vermieten: Platz für vier Personen, Küche und Dusche an Bord. Mindestens eine Woche."},{"id":"i","text":"Gepäckaufbewahrung Hauptbahnhof: Schließfächer in drei Größen, ab 3 Euro pro Tag, geöffnet 6–22 Uhr."},{"id":"j","text":"Stadtführungen zu Fuß: Zwei Stunden durch die Altstadt, täglich um 10 und 15 Uhr, ohne Anmeldung."},{"id":"k","text":"Kanutouren auf der Elbe: Geführte Touren für Anfänger, Ausrüstung inklusive, samstags und sonntags."},{"id":"l","text":"Taxi-Zentrale 24: Bestellung per App oder Telefon, Kartenzahlung möglich, auch Großraumtaxi."}],"situations":[{"n":11,"text":"Sie fliegen früh am Morgen von Frankfurt und brauchen um vier Uhr ein Fahrzeug zum Flughafen."},{"n":12,"text":"Sie möchten einen Tag am See verbringen und dort Fahrräder für die ganze Familie ausleihen."},{"n":13,"text":"Sie fahren mit dem Zug nach Berlin und möchten Ihren schweren Koffer für ein paar Stunden im Bahnhof lassen."},{"n":14,"text":"Sie möchten am Wochenende günstig mit dem Bus nach Hamburg fahren."},{"n":15,"text":"Ihre Tochter möchte in den Sommerferien Englisch lernen und in einer Familie wohnen."},{"n":16,"text":"Sie möchten eine Woche Urlaub mit dem Wohnmobil machen und brauchen ein Fahrzeug für vier Personen."},{"n":17,"text":"Sie besuchen die Stadt zum ersten Mal und möchten in zwei Stunden die wichtigsten Gebäude sehen."},{"n":18,"text":"Sie brauchen für zwei Tage ein Auto, weil Ihr eigenes in der Werkstatt ist."},{"n":19,"text":"Sie möchten in Ihrem Garten einen neuen Zaun bauen und suchen das Material dafür."},{"n":20,"text":"Sie suchen eine Putzhilfe für Ihre Wohnung, zweimal pro Woche."}]}'::jsonb, 10, false, 'telc-deutsch-b1.lv3.03@v1'),
    ('telc-deutsch-b1.sb1.01', 'v1', 'telc-deutsch-b1', 'SB1', 'SB', 1, 'SB1 1', '{"letter":"Liebe Nina,\n\nwie geht es dir? Wir sind endlich im Urlaub! Am Freitag {21} wir in Neapel angekommen. Die Reise war sehr lang, {22} sind wir pünktlich da. Unser Hotel liegt direkt {23} Meer, und wir haben schon {24} Strand gefunden.\n\nGestern haben wir ein kleines Dorf besucht, {25} auf einem Hügel liegt. Leider habe ich meinen Sonnenhut {26}. Kannst du {27} Bruder fragen, ob er noch einen alten Hut hat? Meine Schwester kommt am Wochenende zu Besuch, ich freue mich sehr auf {28}. Das Wasser ist hier übrigens viel {29} als zu Hause.\n\nEs {30} schön, wenn du im August kommen könntest. Sag mir bitte bald Bescheid!\n\nViele Grüße\nSara","gaps":[{"n":21,"options":{"a":"haben","b":"sind","c":"werden"}},{"n":22,"options":{"a":"trotzdem","b":"weil","c":"obwohl"}},{"n":23,"options":{"a":"am","b":"ans","c":"im"}},{"n":24,"options":{"a":"einen ruhigen","b":"ein ruhiger","c":"einem ruhigen"}},{"n":25,"options":{"a":"das","b":"dem","c":"den"}},{"n":26,"options":{"a":"verloren","b":"verliert","c":"verlor"}},{"n":27,"options":{"a":"deinen","b":"dein","c":"deinem"}},{"n":28,"options":{"a":"sie","b":"ihr","c":"ihnen"}},{"n":29,"options":{"a":"wärmer","b":"warm","c":"am wärmsten"}},{"n":30,"options":{"a":"wäre","b":"wird","c":"war"}}]}'::jsonb, 10, false, 'telc-deutsch-b1.sb1.01@v1'),
    ('telc-deutsch-b1.sb1.02', 'v1', 'telc-deutsch-b1', 'SB1', 'SB', 1, 'SB1 2', '{"letter":"Liebe Julia,\n\nendlich habe ich eine neue Wohnung gefunden! {21} drei Wochen bin ich umgezogen, und seitdem schlafe ich viel besser. Die Wohnung ist klein, aber sie ist viel {22} als meine alte.\n\n{23} du mir am Samstag beim Umzug helfen? Meine Nachbarn sind sehr freundlich, besonders die Frau, {24} unter mir wohnt. Sie hat mir am ersten Tag einen Kuchen gebracht, und ich habe {25} sofort zum Kaffee eingeladen.\n\nAm Samstag {26} ich endlich die letzten Kartons aus. Außerdem muss ich noch ein Regal aufbauen: Ich {27} es schon am Montag aufgebaut, aber die Anleitung war auf Schwedisch. Du bist handwerklich viel geschickter als ich, deshalb brauche ich wirklich deine Hilfe.\n\nÜbrigens gibt es in der neuen Straße einen {28} Park, dort können wir im Sommer zusammen grillen. Ich freue mich schon sehr {29} deinen Besuch. Schreib mir bitte, {30} du am Wochenende Zeit hast.\n\nViele Grüße\nSara","gaps":[{"n":21,"options":{"a":"Vor","b":"Seit","c":"In"}},{"n":22,"options":{"a":"größer","b":"groß","c":"am größten"}},{"n":23,"options":{"a":"Kannst","b":"Kann","c":"Können"}},{"n":24,"options":{"a":"die","b":"der","c":"den"}},{"n":25,"options":{"a":"sie","b":"ihr","c":"ihnen"}},{"n":26,"options":{"a":"packe","b":"auspacke","c":"packen"}},{"n":27,"options":{"a":"habe","b":"bin","c":"werde"}},{"n":28,"options":{"a":"großen","b":"großer","c":"großem"}},{"n":29,"options":{"a":"auf","b":"über","c":"an"}},{"n":30,"options":{"a":"ob","b":"wenn","c":"dass"}}]}'::jsonb, 10, false, 'telc-deutsch-b1.sb1.02@v1'),
    ('telc-deutsch-b1.sb1.03', 'v1', 'telc-deutsch-b1', 'SB1', 'SB', 1, 'SB1 3', '{"letter":"Liebe Mama,\n\nich habe tolle Neuigkeiten: Ich habe eine neue Stelle gefunden! {21} Montag arbeite ich in einer großen Firma im Zentrum. Die Arbeit ist besser bezahlt, {22} ich weniger Freizeit habe.\n\nMeine Chefin ist eine {23} Frau, die immer freundlich grüßt. Die Kollegen, {24} ich schon kennengelernt habe, helfen mir sehr. Am ersten Tag habe ich {25} Computer nicht gefunden, aber jetzt klappt alles.\n\nIch muss jeden Tag einen Anzug tragen, weil ich viel {26} Kunden spreche. {27} du mir am Wochenende helfen und meine alten Sachen sortieren? Letzte Woche {28} ich nämlich den Vertrag unterschrieben, und nun muss alles schnell gehen. Vor der Arbeit {29} ich noch einen Deutschkurs besuchen, aber ich weiß nicht, ob ich die Zeit dafür habe.\n\nMein neuer Chef ist übrigens viel {30} als der alte. Ich hoffe, es geht dir gut. Besuchst du mich bald?\n\nViele Grüße\nSara","gaps":[{"n":21,"options":{"a":"Ab","b":"Seit","c":"Vor"}},{"n":22,"options":{"a":"obwohl","b":"weil","c":"deshalb"}},{"n":23,"options":{"a":"nette","b":"netten","c":"netter"}},{"n":24,"options":{"a":"die","b":"denen","c":"der"}},{"n":25,"options":{"a":"meinen","b":"mein","c":"meinem"}},{"n":26,"options":{"a":"mit","b":"für","c":"gegen"}},{"n":27,"options":{"a":"Könntest","b":"Kannst","c":"Konntest"}},{"n":28,"options":{"a":"habe","b":"bin","c":"werde"}},{"n":29,"options":{"a":"möchte","b":"möchtest","c":"möchten"}},{"n":30,"options":{"a":"freundlicher","b":"freundlich","c":"am freundlichsten"}}]}'::jsonb, 10, false, 'telc-deutsch-b1.sb1.03@v1'),
    ('telc-deutsch-b1.sb2.01', 'v1', 'telc-deutsch-b1', 'SB2', 'SB', 2, 'SB2 1', '{"letter":"Sehr geehrte Damen und Herren,\n\n{31} schreibe ich Ihnen, weil ich mich in München anmelden möchte. Ich {32} am 1. September in die Gartenstraße 14 gezogen. Leider habe ich bis heute keinen Termin bekommen, {33} ich dreimal angerufen habe.\n\n{34} ich alle nötigen Unterlagen mitbringen muss, möchte ich das vorher wissen. {35} Sie mir bitte einen Termin am Nachmittag geben? Meine Wohnung gehört {36} Schwester, die ebenfalls in München lebt.\n\n{37} meines Urlaubs war ich nicht erreichbar, das tut mir leid. Außerdem {38} ich noch meinen Mietvertrag übersetzen lassen. Ich habe schon dreimal angerufen, {39} hat sich niemand gemeldet.\n\nVielen Dank im Voraus. Bitte schicken Sie {40} eine kurze Bestätigung.\n\nMit freundlichen Grüßen\nAli Yildirim","bank":[{"id":"a","word":"DESHALB"},{"id":"b","word":"BIN"},{"id":"c","word":"OBWOHL"},{"id":"d","word":"DA"},{"id":"e","word":"KÖNNTEN"},{"id":"f","word":"MEINER"},{"id":"g","word":"WÄHREND"},{"id":"h","word":"MUSS"},{"id":"i","word":"TROTZDEM"},{"id":"j","word":"MIR"},{"id":"k","word":"SEIT"},{"id":"l","word":"NACH"},{"id":"m","word":"IHNEN"},{"id":"n","word":"WÄRE"},{"id":"o","word":"DÜRFEN"}],"gaps":[{"n":31},{"n":32},{"n":33},{"n":34},{"n":35},{"n":36},{"n":37},{"n":38},{"n":39},{"n":40}]}'::jsonb, 10, false, 'telc-deutsch-b1.sb2.01@v1'),
    ('telc-deutsch-b1.sb2.02', 'v1', 'telc-deutsch-b1', 'SB2', 'SB', 2, 'SB2 2', '{"letter":"Sehr geehrte Frau Weber,\n\n{31} Ihrer Anzeige bewerbe ich mich um ein Praktikum im Bereich Marketing. Ich studiere Betriebswirtschaft {32} der Universität Köln und habe bereits zwei Semester abgeschlossen.\n\n{33} ich mein Studium im Sommer beende, möchte ich vorher praktische Erfahrung sammeln. In meinem Nebenjob {34} ich schon Kunden beraten und kleine Werbekampagnen planen. {35} Sie mir bitte mit, ob auch ein Praktikum von drei Monaten möglich ist.\n\nIch {36} mich sehr freuen, wenn Sie mir eine Chance geben. {37} meines Studiums habe ich außerdem einen Kurs in Online-Marketing besucht. Meine Kenntnisse in Spanisch sind {38} als in Englisch, deshalb könnte ich auch internationale Kunden betreuen.\n\n{39} Sie meine Bewerbung bitte prüfen? Bitte senden Sie {40} bis Ende April eine kurze Antwort. Über eine Einladung zum Gespräch würde ich mich sehr freuen.\n\nMit freundlichen Grüßen\nLena Hoffmann","bank":[{"id":"a","word":"WEGEN"},{"id":"b","word":"AN"},{"id":"c","word":"DA"},{"id":"d","word":"KONNTE"},{"id":"e","word":"TEILEN"},{"id":"f","word":"WÜRDE"},{"id":"g","word":"WÄHREND"},{"id":"h","word":"BESSER"},{"id":"i","word":"KÖNNTEN"},{"id":"j","word":"MIR"},{"id":"k","word":"OHNE"},{"id":"l","word":"TROTZ"},{"id":"m","word":"IHNEN"},{"id":"n","word":"MÜSSTE"},{"id":"o","word":"SEIT"}],"gaps":[{"n":31},{"n":32},{"n":33},{"n":34},{"n":35},{"n":36},{"n":37},{"n":38},{"n":39},{"n":40}]}'::jsonb, 10, false, 'telc-deutsch-b1.sb2.02@v1'),
    ('telc-deutsch-b1.sb2.03', 'v1', 'telc-deutsch-b1', 'SB2', 'SB', 2, 'SB2 3', '{"letter":"Sehr geehrte Damen und Herren,\n\n{31} Ihrer Internetseite habe ich erfahren, dass Sie im Herbst einen Kurs für Deutsch B1 anbieten. Ich {32} mich gern dafür anmelden.\n\n{33} ich seit zwei Jahren in Deutschland lebe, spreche ich schon recht gut, aber {34} möchte ich die Prüfung sicher bestehen. {35} Sie mir bitte mitteilen, wann der Kurs beginnt und wie viel er kostet?\n\nIch arbeite {36} Montag bis Freitag bis 17 Uhr, deshalb kann ich nur abends teilnehmen. {37} der Kurs am Wochenende stattfindet, hätte ich mehr Zeit. Mein Kollege hat den Kurs schon besucht und sagt, er sei {38} als andere Kurse.\n\nBitte schicken Sie {39} außerdem Informationen über die Prüfung. Ich {40} Ihre AGB bereits gelesen und akzeptiere sie. Über eine baldige Antwort würde ich mich sehr freuen.\n\nMit freundlichen Grüßen\nMarta Kowalska","bank":[{"id":"a","word":"AUF"},{"id":"b","word":"WÜRDE"},{"id":"c","word":"DA"},{"id":"d","word":"TROTZDEM"},{"id":"e","word":"KÖNNTEN"},{"id":"f","word":"VON"},{"id":"g","word":"WENN"},{"id":"h","word":"BESSER"},{"id":"i","word":"MIR"},{"id":"j","word":"HABE"},{"id":"k","word":"SEIT"},{"id":"l","word":"OHNE"},{"id":"m","word":"NACH"},{"id":"n","word":"IHNEN"},{"id":"o","word":"WÄREN"}],"gaps":[{"n":31},{"n":32},{"n":33},{"n":34},{"n":35},{"n":36},{"n":37},{"n":38},{"n":39},{"n":40}]}'::jsonb, 10, false, 'telc-deutsch-b1.sb2.03@v1')
