    INSERT INTO "__SCHEMA__".objective_key
      (set_id, version, answers, explanations, transcript)
    VALUES
    ('telc-deutsch-b1.hv1.01', 'v1', '{"41":true,"42":false,"43":true,"44":true,"45":false}'::jsonb, '{"41":"Anna sagt, dass der Kinobesuch am Freitag nicht klappt, weil sie länger arbeiten muss.","42":"Ben kann nicht kommen, weil seine Eltern zu Besuch sind – nicht wegen der Arbeit.","43":"Lisa sagt, dass sie noch zehn Minuten am Eingang wartet und dann nach Hause fährt.","44":"Peter hat mit dem Fahrrad eine Panne und fragt, ob man ihn mit dem Auto abholt.","45":"Im Text ist von sechs Personen die Rede, nicht von vier."}'::jsonb, '[Sprecherin 1]: Hallo Tim, hier ist Anna. Ich muss dir leider absagen: Der Kinobesuch am Freitag klappt nicht, weil ich länger arbeiten muss. Hast du am Sonntag Zeit? Wir könnten um vier ins Museum gehen und danach etwas essen.

[Sprecher 2]: Hallo, hier ist Ben. Ich kann am Samstag leider nicht zum Fußball kommen, weil meine Eltern zu Besuch sind. Können wir uns nächste Woche treffen? Ich rufe dich am Abend noch einmal an.

[Sprecherin 3]: Hi, hier ist Lisa. Ich stehe vor dem Restaurant, aber ich sehe dich nicht. Wir wollten uns doch um sieben treffen. Ich warte noch zehn Minuten am Eingang, dann fahre ich nach Hause.

[Sprecher 4]: Hallo, hier ist Peter. Ich bin mit dem Fahrrad unterwegs und habe eine Panne. Kannst du mich mit dem Auto abholen? Ich stehe an der Kreuzung Bahnhofstraße und warte dort.

[Sprecherin 5]: Guten Abend, hier ist Familie Kaya. Wir möchten für Samstag einen Tisch für sechs Personen reservieren, am liebsten draußen. Bitte rufen Sie uns bis Donnerstag zurück, unsere Nummer ist 0221 98 76 54.'),
    ('telc-deutsch-b1.hv1.02', 'v1', '{"41":true,"42":false,"43":true,"44":false,"45":true}'::jsonb, '{"41":"Jonas sagt, sein Zug hat zwanzig Minuten Verspätung, deshalb schafft er das Mittagessen nicht.","42":"Laut Ansage fährt der ICE nach München heute von Gleis zwölf.","43":"Der Flug wurde gestrichen und die Airline hat einen neuen Flug für morgen früh um sechs Uhr angeboten.","44":"Im Text steht, dass das Frühstück im Preis enthalten ist.","45":"Der Fahrradverleih bittet darum, bis spätestens achtzehn Uhr zu kommen."}'::jsonb, '[Sprecherin 1]: Hallo Marie, hier ist Jonas. Ich bin am Bahnhof angekommen, aber mein Zug nach Hamburg hat zwanzig Minuten Verspätung. Ich schaffe es also nicht mehr zum Mittagessen. Warte bitte nicht auf mich, ich komme direkt ins Hotel.

[Sprecher 2]: Liebe Fahrgäste, der ICE nach München fährt heute nicht von Gleis acht, sondern von Gleis zwölf. Der Zug hat außerdem zehn Minuten Verspätung. Bitte beachten Sie die Durchsagen.

[Sprecherin 3]: Hi, hier ist Sofia. Unser Flug nach Lissabon wurde leider gestrichen. Die Airline hat uns aber schon einen neuen Flug für morgen früh um sechs Uhr angeboten. Können wir uns heute Abend noch treffen?

[Sprecher 4]: Guten Tag, hier ist das Hotel Sonne. Ihr Zimmer ist ab vierzehn Uhr fertig. Das Frühstück ist im Preis enthalten und wird von sieben bis zehn Uhr serviert. Der Parkplatz kostet acht Euro pro Tag.

[Sprecherin 5]: Hallo, hier ist der Fahrradverleih am See. Ihre reservierten Räder stehen ab neun Uhr für Sie bereit. Bitte bringen Sie einen Ausweis mit und kommen Sie bis spätestens achtzehn Uhr, sonst geben wir die Räder weiter.'),
    ('telc-deutsch-b1.hv1.03', 'v1', '{"41":true,"42":true,"43":false,"44":false,"45":true}'::jsonb, '{"41":"Die Praxis schlägt Donnerstag um halb elf oder Freitag um zwei Uhr vor.","42":"Laura sagt, dass sie morgen um zehn kommt und die Rezepte von der Apotheke mitbringt.","43":"Der Kurs am Dienstag fällt aus, weil die Trainerin krank ist.","44":"Ein Medikament ist nicht lieferbar und kommt erst am Montag.","45":"Die Zahnarztpraxis erinnert an den Kontrolltermin am Freitag um elf Uhr."}'::jsonb, '[Sprecherin 1]: Guten Tag, hier ist die Praxis Dr. Noll. Ihr Termin am Mittwoch um neun Uhr muss leider verschoben werden. Wir hätten noch Donnerstag um halb elf oder Freitag um zwei Uhr frei. Bitte rufen Sie uns zurück.

[Sprecher 2]: Hallo Papa, hier ist Laura. Denk bitte daran, dass du heute Abend deine Tabletten nehmen musst. Ich komme morgen um zehn und bringe die neuen Rezepte von der Apotheke mit.

[Sprecherin 3]: Guten Morgen, hier ist das Fitnessstudio Aktiv. Ihr Kurs am Dienstag fällt diese Woche aus, weil die Trainerin krank ist. Sie können aber am Donnerstag um achtzehn Uhr am gleichen Kurs teilnehmen. Eine Anmeldung ist nicht nötig.

[Sprecher 4]: Hallo, hier ist die Apotheke am Markt. Ihre Bestellung ist da, aber leider ist ein Medikament nicht lieferbar. Wir bekommen es erst am Montag. Möchten Sie warten oder soll ich mit dem Arzt sprechen?

[Sprecherin 5]: Guten Tag, hier ist die Zahnarztpraxis Dr. Berg. Wir möchten Sie daran erinnern, dass Sie am Freitag um elf Uhr einen Kontrolltermin haben. Bitte bringen Sie Ihre Versichertenkarte mit.'),
    ('telc-deutsch-b1.hv2.01', 'v1', '{"46":false,"47":true,"48":false,"49":true,"50":true,"51":false,"52":true,"53":true,"54":false,"55":true}'::jsonb, '{"46":"Sie rät ausdrücklich davon ab und empfiehlt kleine Veränderungen im Alltag.","47":"Frau Baum sagt, dass man eine strenge Diät meistens nur zwei oder drei Wochen durchhält.","48":"Sie sagt, das stimme nur zum Teil; saisonales Gemüse und Hülsenfrüchte sind nicht teuer.","49":"Sie sagt am Ende des Absatzes: „Die braucht niemand.“","50":"Frau Baum berichtet, dass sie immer mehr Zehnjährige mit Übergewicht sehen.","51":"Sie sagt, ein Teil sei gut und nur ein Teil gefährlich.","52":"Sie empfiehlt immer, bei einer Ärztin oder einem Arzt nachzufragen.","53":"Der Kurs dauert acht Wochen, und man trifft sich einmal pro Woche für neunzig Minuten.","54":"Frau Baum betont, dass niemand mitmachen muss; Freiwilligkeit ist wichtiger als Druck.","55":"Für kleine Betriebe gibt es einen festen Preis von 600 Euro für den ganzen Kurs."}'::jsonb, '[Moderator]: Herzlich willkommen zu unserer Sendung „Gesund leben“. Heute ist Frau Dr. Karin Baum bei uns, sie arbeitet als Ernährungsberaterin in einer großen Praxis in Leipzig. Frau Baum, viele Menschen wollen sich gesünder ernähren, aber sie wissen nicht, wo sie anfangen sollen. Was raten Sie?

[Gast]: Guten Tag. Ja, das ist wirklich ein großes Thema. Mein wichtigster Rat ist: Fangen Sie nicht mit einer strengen Diät an. Wer plötzlich gar keinen Zucker und kein Fett mehr isst, hält das meistens nur zwei oder drei Wochen durch. Besser ist es, jeden Tag eine kleine Veränderung einzubauen. Zum Beispiel: statt Limonade Wasser, statt Weißbrot Vollkornbrot.

[Moderator]: Viele Leute sagen, dass gesundes Essen teuer ist. Stimmt das?

[Gast]: Das stimmt nur zum Teil. Fertigprodukte und Fast Food sind oft billiger, das ist wahr. Aber Gemüse aus der Saison, Hülsenfrüchte wie Linsen und Bohnen und Haferflocken kosten nicht viel. Wer auf dem Markt kurz vor Ladenschluss einkauft, bekommt das Gemüse manchmal sogar billiger. Teuer wird es vor allem, wenn man viele „gesunde“ Produkte kauft, die in bunten Packungen werben – zum Beispiel spezielle Riegel oder Säfte. Die braucht niemand.

[Moderator]: Sie arbeiten auch mit Kindern und Jugendlichen. Was hat sich in den letzten Jahren verändert?

[Gast]: Leider nicht nur Gutes. Die Kinder trinken viel mehr süße Getränke als früher, und sie bewegen sich weniger. In unserer Praxis sehen wir immer mehr Zehnjährige mit Übergewicht. Gleichzeitig interessieren sich viele Jugendliche sehr für Ernährung, besonders seit es diese Videos im Internet gibt. Das nutzen wir in den Kursen: Wir kochen mit den Jugendlichen und sprechen darüber, was in den Videos stimmt und was nicht.

[Moderator]: Was halten Sie von diesen Videos?

[Gast]: Ein Teil ist gut, ein Teil ist gefährlich. Ich habe nichts gegen Rezepte im Internet. Aber wenn jemand ohne Ausbildung sagt, man solle keine Medikamente mehr nehmen oder nur noch eine einzige Sache essen, dann ist das gefährlich. Ich empfehle immer, bei einer Ärztin oder einem Arzt nachzufragen.

[Moderator]: Sie bieten auch Kurse für Firmen an. Wie läuft so ein Kurs ab?

[Gast]: Ein Kurs dauert bei uns acht Wochen, und wir treffen uns einmal pro Woche für neunzig Minuten. In der ersten Stunde schauen wir gemeinsam, was die Teilnehmer schon wissen und was sie ändern möchten. Danach kochen wir in jeder Stunde ein einfaches Gericht, das in zwanzig Minuten fertig ist. Die Teilnehmer bekommen also keine komplizierten Rezepte, sondern Ideen für den Alltag. Wichtig ist: Niemand muss mitmachen, der nicht will. Freiwilligkeit funktioniert viel besser als Druck.

[Moderator]: Und was kostet so ein Firmentraining?

[Gast]: Das hängt von der Firmengröße ab. Für kleine Betriebe mit weniger als zwanzig Mitarbeitern bieten wir einen festen Preis von 600 Euro für den ganzen Kurs an. Größere Firmen zahlen 40 Euro pro Person. Die Krankenkassen übernehmen die Kosten leider nicht, aber einige Firmen bekommen einen Zuschuss vom Land.

[Moderator]: Frau Baum, vielen Dank für das Gespräch.'),
    ('telc-deutsch-b1.hv2.02', 'v1', '{"46":true,"47":false,"48":true,"49":true,"50":false,"51":true,"52":false,"53":true,"54":false,"55":true}'::jsonb, '{"46":"Er sagt, die jungen Leute sind heute viel unsicherer, wenn sie zum ersten Mal im Auto sitzen.","47":"Im Gegenteil: Viele kommen aus Familien, in denen niemand ein Auto hat.","48":"Früher zahlte man 1.200 bis 1.500 Euro, heute oft 2.500 Euro oder mehr.","49":"So kann man sich im praktischen Unterricht voll auf das Fahren konzentrieren.","50":"Sie muss außerdem mindestens dreißig Jahre alt sein, seit fünf Jahren den Führerschein haben und darf höchstens einen Punkt haben.","51":"Herr Reinhardt nennt genau diese Bedingung für die Begleitperson.","52":"Die Fahrschule braucht eine teure Ladestation, und das Laden dauert länger als das Tanken.","53":"Er sagt, dass in zehn Jahren fast alle Fahrschulen mit E-Autos fahren werden.","54":"Er betont: „Fahren lernt man nicht in zwei Wochen.“","55":"Er wünscht sich, dass sie die Regeln nicht nur für die Prüfung lernen, sondern weil sie im Verkehr wichtig sind."}'::jsonb, '[Moderator]: Willkommen bei „Auto und mehr“. Zu Gast ist Herr Thomas Reinhardt, Fahrlehrer aus Dortmund. Herr Reinhardt, Sie unterrichten seit über zwanzig Jahren. Haben sich Ihre Fahrschüler in dieser Zeit verändert?

[Gast]: Ja, deutlich. Die jungen Leute sind heute viel unsicherer, wenn sie zum ersten Mal im Auto sitzen. Sie kennen sich mit dem Handy perfekt aus, aber sie haben oft Angst vor dem Verkehr. Außerdem kommen viele Fahrschüler aus Familien, in denen niemand ein Auto hat. Für sie ist alles neu, auch das Tanken.

[Moderator]: Ist der Führerschein teurer geworden?

[Gast]: Leider ja. Vor zwanzig Jahren haben die meisten zwischen 1.200 und 1.500 Euro bezahlt. Heute sind es oft 2.500 Euro oder mehr. Der Grund sind höhere Kosten für Benzin, Versicherung und die Fahrzeuge selbst. Wer zusätzlich viele Fahrstunden braucht, kann auch bei 3.000 Euro landen.

[Moderator]: Was raten Sie, damit es billiger wird?

[Gast]: Zuerst: Üben Sie die Theorie nicht erst am Ende. Wer die Theorieprüfung früh besteht, kann sich im praktischen Unterricht voll auf das Fahren konzentrieren und braucht weniger Stunden. Zweitens: Fahren Sie privat, wenn es möglich ist. In Deutschland darf man ab siebzehn mit Begleitung fahren. Drittens: Vergleichen Sie die Preise der Fahrschulen, aber schauen Sie nicht nur auf den Preis. Eine billige Fahrschule mit schlechter Ausbildung kostet am Ende mehr.

[Moderator]: Was ist mit dem Führerschein ab siebzehn?

[Gast]: Das Modell „begleitetes Fahren“ gibt es seit vielen Jahren, und die Erfahrung ist gut. Wer ab siebzehn fährt, hat später weniger Unfälle. Allerdings muss eine Begleitperson dabei sein, und diese Person muss bestimmte Bedingungen erfüllen: Sie muss mindestens dreißig Jahre alt sein und seit fünf Jahren einen Führerschein haben. Die Begleitperson darf außerdem nicht mehr als einen Punkt in Flensburg haben.

[Moderator]: Und was sagen Sie zum Thema E-Auto in der Fahrschule?

[Gast]: Wir haben seit zwei Jahren zwei E-Autos. Die Fahrschüler finden sie toll, weil sie leise sind und automatisch schalten. Aber für uns als Fahrschule ist es kompliziert: Wir brauchen eine eigene Ladestation, und die ist teuer. Außerdem dauert das Laden länger als das Tanken. Trotzdem glaube ich, dass in zehn Jahren fast alle Fahrschulen mit E-Autos fahren.

[Moderator]: Eine letzte Frage: Was wünschen Sie sich von Ihren Fahrschülern?

[Gast]: Ich wünsche mir, dass sie geduldig bleiben. Fahren lernt man nicht in zwei Wochen. Und ich wünsche mir, dass sie die Regeln nicht nur für die Prüfung lernen, sondern weil sie im Verkehr wichtig sind. Wer rücksichtsvoll fährt, kommt am Ende sicherer an.

[Moderator]: Vielen Dank, Herr Reinhardt.'),
    ('telc-deutsch-b1.hv2.03', 'v1', '{"46":true,"47":false,"48":true,"49":false,"50":true,"51":false,"52":true,"53":false,"54":true,"55":false}'::jsonb, '{"46":"Frau Kessler nennt genau diese Zahl von etwa 620 Kilogramm pro Jahr.","47":"Sie sagt ausdrücklich, dass Recycling allein nicht reicht und wir zuerst weniger produzieren müssen.","48":"Sie empfiehlt, den Becher kurz auszuspülen, weil Reste von Milchprodukten das Recycling stören.","49":"Benutzte Taschentücher und Küchenpapier gehören in den Restmüll.","50":"Frau Kessler sagt, blaue Flaschen sind ein Problem und gehören deshalb meistens zum grünen Glas.","51":"Kleine Betriebe wie ein Kiosk mit wenigen Mitarbeitern sind davon ausgenommen.","52":"Genau diese Zahl nennt Frau Kessler mit Verweis auf Studien.","53":"Es gibt ein einheitliches Pfandsystem, bei dem man den Becher in jedem teilnehmenden Café abgeben kann.","54":"Das ist einer der fünf Tipps, die sie am Ende gibt.","55":"Sie hat 30 Prozent weniger Restmüll produziert, nicht mehr."}'::jsonb, '[Moderator]: In unserer Sendung „Umwelt heute“ sprechen wir mit Frau Julia Kessler. Sie berät Kommunen in Fragen der Abfallvermeidung. Frau Kessler, warum wird das Thema gerade jetzt so wichtig?

[Gast]: Weil die Mengen nicht sinken. In Deutschland produziert jeder Mensch im Durchschnitt etwa 620 Kilogramm Haushaltsabfall pro Jahr. Zwar trennen die meisten Bürger sehr gewissenhaft, aber das Recycling allein reicht nicht. Wir müssen zuerst weniger produzieren.

[Moderator]: Viele Menschen sagen, sie seien unsicher, wie sie den Müll richtig trennen. Was sind die häufigsten Fehler?

[Gast]: Der häufigste Fehler ist der Joghurtbecher. Viele werfen ihn ungespült in den gelben Sack. Das ist nicht falsch, aber besser ist es, den Becher kurz auszuspülen, denn Reste von Milchprodukten stören das Recycling. Ein zweiter Fehler: benutzte Taschentücher und Küchenpapier gehören in den Restmüll, nicht ins Papier. Und drittens: Glas wird nach Farben getrennt, aber blaue Flaschen sind ein Problem, deshalb gehören sie meistens zum grünen Glas.

[Moderator]: Sie setzen sich seit Jahren für Mehrwegverpackungen ein. Wie läuft das?

[Gast]: Die Idee ist einfach: Man gibt einen Becher oder eine Box zurück und bekommt das Pfand. Seit 2023 müssen größere Gastronomiebetriebe in Deutschland Mehrweg anbieten, wenn sie Einweg-Plastik verkaufen. Kleine Betriebe, zum Beispiel ein Kiosk mit wenigen Mitarbeitern, sind davon ausgenommen. In der Praxis funktioniert das System aber nur, wenn viele Läden mitmachen. Sonst behält der Kunde am Ende zehn verschiedene Becher zu Hause.

[Moderator]: Kritiker sagen, Mehrwegbecher seien schlechter für die Umwelt, weil man sie mit heißem Wasser spülen muss. Was sagen Sie dazu?

[Gast]: Diese Rechnung stimmt nur, wenn der Becher nur ein einziges Mal benutzt wird. Studien zeigen: Ab etwa zwanzig Nutzungen ist der Mehrwegbecher deutlich besser als der Einwegbecher. Wichtig ist also, dass die Becher oft zurückkommen. Deshalb arbeiten wir mit einem einheitlichen Pfandsystem, bei dem man den Becher in jedem teilnehmenden Café abgeben kann.

[Moderator]: Was kann jeder Einzelne tun?

[Gast]: Fünf Dinge: eine eigene Tasche mitnehmen, eine Trinkflasche statt Flaschen kaufen, Obst ohne Plastikverpackung wählen, Brot in der Bäckerei in einem Stoffbeutel kaufen und Geräte reparieren lassen statt neue zu kaufen. Das klingt nach wenig, aber wenn das Millionen Menschen machen, ändert sich sehr viel.

[Moderator]: Und was macht Ihnen bei Ihrer Arbeit am meisten Freude?

[Gast]: Wenn ich sehe, dass eine Schule oder eine Stadt etwas verändert. Letztes Jahr hat eine kleine Gemeinde in Bayern mit unseren Tipps 30 Prozent weniger Restmüll produziert. Das war ein schöner Moment.

[Moderator]: Frau Kessler, danke für das Gespräch.'),
    ('telc-deutsch-b1.hv3.01', 'v1', '{"56":true,"57":true,"58":false,"59":true,"60":false}'::jsonb, '{"56":"Die Bäckerei nennt genau diesen Abholtermin am Freitag.","57":"Wegen der Inventur schließt der Supermarkt heute ausnahmsweise um neunzehn Uhr.","58":"Die Lieferung am Dienstag ist nicht möglich; der neue Termin ist Donnerstag zwischen dreizehn und siebzehn Uhr.","59":"Wegen der Bauarbeiten endet die Linie 4 heute am Marktplatz, dort fahren Busse weiter.","60":"Man kann das Buch bis Samstag abholen; am Montag wird es weitergegeben."}'::jsonb, '[Anrufbeantworter]: Guten Tag, hier ist die Bäckerei Krause. Ihre Torte für die Geburtstagsfeier ist fertig. Sie können sie am Freitag zwischen acht und sechzehn Uhr abholen. Bitte bringen Sie die Rechnung mit. Am Samstag schließen wir schon um zwölf Uhr.

[Durchsage]: Liebe Kundinnen und Kunden, unser Supermarkt schließt heute ausnahmsweise bereits um neunzehn Uhr, weil wir eine Inventur machen. Ab morgen sind wir wieder wie gewohnt bis zweiundzwanzig Uhr für Sie da. Vielen Dank für Ihr Verständnis.

[Anrufbeantworter]: Hallo, hier ist Mehmet vom Möbelhaus Wohnwelt. Ihr Sofa kann leider nicht am Dienstag geliefert werden. Der neue Liefertermin ist Donnerstag zwischen dreizehn und siebzehn Uhr. Bitte rufen Sie uns an, wenn Ihnen das nicht passt.

[Durchsage]: Sehr geehrte Fahrgäste, wegen Bauarbeiten fährt die Straßenbahnlinie 4 heute nur bis zur Haltestelle Marktplatz. Von dort fahren Busse weiter in Richtung Hauptbahnhof. Die Bauarbeiten dauern noch bis Ende des Monats.

[Anrufbeantworter]: Guten Tag, hier ist die Stadtbibliothek. Das Buch, das Sie bestellt haben, ist eingetroffen. Sie können es bis Samstag abholen. Die Ausleihfrist beträgt vier Wochen. Wenn Sie es nicht abholen, geben wir es am Montag an den nächsten Interessenten weiter.'),
    ('telc-deutsch-b1.hv3.02', 'v1', '{"56":false,"57":true,"58":true,"59":false,"60":true}'::jsonb, '{"56":"Laut Durchsage fährt der Zug heute von Gleis neun, nicht von Gleis zwölf.","57":"Der neue Abflug ist um sechzehn Uhr fünfzig, das Gate ist B 12.","58":"Das Reisebüro weist ausdrücklich auf diese sechs Monate hin.","59":"Wegen eines Unfalls fahren die Züge heute nicht über die Station Universität.","60":"Laut Buchungsbestätigung kostet das Abendessen neun Euro pro Person."}'::jsonb, '[Durchsage]: Information für alle Reisenden: Der Regionalexpress nach Stuttgart, Abfahrt zwölf Uhr siebzehn, fährt heute von Gleis neun. Der Zug hat etwa fünf Minuten Verspätung. Wir bitten um Ihr Verständnis.

[Durchsage]: Liebe Fluggäste, der Flug LH 442 nach Rom ist leider um zwei Stunden verschoben. Der neue Abflug ist um sechzehn Uhr fünfzig. Bitte gehen Sie zum Gate B 12. Getränke erhalten Sie am Gate kostenlos.

[Anrufbeantworter]: Guten Tag, hier ist das Reisebüro Sonnenschein. Ihre Reiseunterlagen für den Urlaub in Griechenland sind da. Sie können sie ab morgen abholen. Denken Sie bitte daran, dass Ihr Reisepass noch mindestens sechs Monate gültig sein muss. Unser Büro ist am Mittwochnachmittag geschlossen.

[Durchsage]: Achtung, eine wichtige Information für die Fahrgäste der Linie S 3: Wegen eines Unfalls fahren die Züge heute nicht über die Station Universität. Bitte benutzen Sie die Buslinie 25 ab der Haltestelle Rathaus. Die Störung dauert voraussichtlich bis achtzehn Uhr.

[Anrufbeantworter]: Hallo, hier ist die Jugendherberge am See. Ihre Buchung für vier Personen vom 3. bis 10. Juli ist bestätigt. Das Frühstück kostet sechs Euro pro Person, das Abendessen neun Euro. Fahrräder können Sie für fünf Euro pro Tag ausleihen. Bitte zahlen Sie bei der Ankunft in bar.'),
    ('telc-deutsch-b1.hv3.03', 'v1', '{"56":false,"57":true,"58":false,"59":true,"60":true}'::jsonb, '{"56":"Das Training am Mittwoch fällt aus, weil die Halle renoviert wird; am Freitag trainiert man draußen.","57":"Der neue Termin ist der 14. März, Beginn um neunzehn Uhr im Vereinsheim.","58":"Der Kurs wurde auf Samstag um elf Uhr verschoben, weil Frau Sommer krank ist.","59":"Der Elternabend beginnt erst um neunzehn Uhr dreißig, der Raum bleibt Raum 204.","60":"Die Stadtbücherei nennt sechs Wochen Dauer und 25 Euro Kursgebühr."}'::jsonb, '[Anrufbeantworter]: Guten Tag, hier ist der Sportverein Blau-Weiß. Das Training der Jugendmannschaft fällt am Mittwoch aus, weil die Halle renoviert wird. Am Freitag trainieren wir stattdessen draußen auf dem Sportplatz, von sechzehn bis achtzehn Uhr.

[Durchsage]: Liebe Mitglieder, unsere Jahreshauptversammlung findet in diesem Jahr am 14. März statt, nicht wie geplant am 7. März. Beginn ist um neunzehn Uhr im Vereinsheim. Bitte bringen Sie Ihren Mitgliedsausweis mit.

[Anrufbeantworter]: Hallo, hier ist die Musikschule Klang. Der Gitarrenkurs am Donnerstag muss leider verschoben werden, weil Frau Sommer krank ist. Der Kurs findet jetzt am Samstag um elf Uhr statt. Fragen beantworten wir unter der Nummer 0341 55 66 77.

[Durchsage]: Achtung, liebe Eltern: Der Elternabend der Klasse 4b beginnt morgen nicht um achtzehn Uhr, sondern erst um neunzehn Uhr dreißig. Der Raum bleibt derselbe, Raum 204 im ersten Stock. Wir bitten um pünktliches Erscheinen.

[Anrufbeantworter]: Guten Tag, hier ist die Stadtbücherei. Wir möchten Sie daran erinnern, dass der Lesekurs für Erwachsene am Montag beginnt. Er dauert sechs Wochen und kostet 25 Euro. Anmelden können Sie sich noch bis Freitag im Internet.'),
    ('telc-deutsch-b1.lv1.01', 'v1', '{"1":"b","2":"c","3":"f","4":"g","5":"d"}'::jsonb, '{"_set_why":{"1":"In Text 1 wird ein Zimmer in einer Wohngemeinschaft angeboten, und Nichtraucher werden ausdrücklich verlangt.","2":"Text 2 beschreibt eine Familie mit zwei Kindern, die vier Zimmer und einen Garten sucht.","3":"Text 3 ist die Anzeige eines Nachmieters für eine kleine Wohnung mit einem Zimmer im Zentrum.","4":"In Text 4 sucht eine 68-jährige Person eine Wohnung im Erdgeschoss mit Balkon.","5":"Text 5 beschreibt einen Studenten, der ein möbliertes Zimmer in Uninähe sucht."}}'::jsonb, NULL),
    ('telc-deutsch-b1.lv1.02', 'v1', '{"1":"a","2":"b","3":"c","4":"d","5":"e"}'::jsonb, '{"_set_why":{"1":"Text 1 sucht eine Aushilfe, die nur am Wochenende im Café arbeitet.","2":"In Text 2 wird ein Praktikum im Marketing für Studierende angeboten.","3":"Text 3 beschreibt eine Stelle im Lager mit Frühschicht und Führerschein.","4":"Text 4 ist die Suche einer Krankenschwester nach einer Teilzeitstelle.","5":"Text 5 sucht einen Deutschlehrer für Abendkurse."}}'::jsonb, NULL),
    ('telc-deutsch-b1.lv1.03', 'v1', '{"1":"a","2":"b","3":"c","4":"d","5":"e"}'::jsonb, '{"_set_why":{"1":"Text 1 bietet einen Yoga-Kurs für Anfänger am Abend an.","2":"In Text 2 geht es um einen Computerkurs für Seniorinnen und Senioren.","3":"Text 3 ist ein Schwimmkurs für Kinder ab fünf Jahren.","4":"Text 4 beschreibt einen Fotokurs, bei dem man in der Stadt fotografiert.","5":"Text 5 ist ein Abendkurs Deutsch B1 mit Prüfungsvorbereitung."}}'::jsonb, NULL),
    ('telc-deutsch-b1.lv2.01', 'v1', '{"6":"b","7":"a","8":"a","9":"b","10":"a"}'::jsonb, '{"6":"Im ersten Absatz steht, dass Autos einige Straßen nicht mehr benutzen dürfen und dort breite Radwege entstehen.","7":"Laut Stadtverwaltung ist die Zahl der Radfahrer in fünf Jahren um fast die Hälfte gestiegen.","8":"Die Geschäftsleute in der Innenstadt befürchten, dass ihre Kunden nicht mehr mit dem Auto kommen und weniger einkaufen.","9":"Die Stadt sagt, dass die Parkhäuser am Rand erhalten bleiben und ein kostenloser Bus alle zehn Minuten fährt.","10":"Im letzten Absatz steht, dass es während der Bauarbeiten an manchen Tagen zu Staus kommen kann."}'::jsonb, NULL),
    ('telc-deutsch-b1.lv2.02', 'v1', '{"6":"a","7":"a","8":"a","9":"b","10":"b"}'::jsonb, '{"6":"Ärzte warnen, dass langes Sitzen Rücken- und Kopfschmerzen und sogar Herzprobleme verursachen kann.","7":"Die Firma hat vor zwei Jahren begonnen, höhenverstellbare Tische zu kaufen.","8":"Nach Angaben der Personalabteilung sind die Fehltage im letzten Jahr um zwanzig Prozent gesunken.","9":"Einige Beschäftigte sagen, dass die Bewegungspause in der Arbeitszeit liegt und sie danach länger bleiben müssen.","10":"Die AOK rät, mit einfachen Mitteln anzufangen; wichtig ist, dass die Chefs selbst mitmachen."}'::jsonb, NULL),
    ('telc-deutsch-b1.lv2.03', 'v1', '{"6":"a","7":"a","8":"a","9":"a","10":"a"}'::jsonb, '{"6":"Die Bahn will ab Juni zusätzliche Züge an die Nordsee und in die Alpen einsetzen.","7":"Kinder unter sechzehn Jahren fahren kostenlos, wenn mindestens ein Elternteil ein Ticket kauft.","8":"Wer sein Ticket vier Wochen vor der Reise bucht, bekommt dreißig Prozent Rabatt.","9":"Reisende können den Koffer schon am Abend vor der Reise abgeben; er wird zum Zielbahnhof gebracht.","10":"Die Sprecherin des Fahrgastverbands sagt, dass die Bahn für eine Familie mit zwei Kindern teurer ist als das Auto."}'::jsonb, NULL),
    ('telc-deutsch-b1.lv3.01', 'v1', '{"11":"a","12":"b","13":"g","14":"h","15":"d","16":"i","17":"f","18":"e","19":"x","20":"x"}'::jsonb, '{"11":"Anzeige a bietet einen Möbeltransport mit Transporter und zwei Helfern an.","12":"In Anzeige b steht, dass Teppiche und Sofas direkt beim Kunden zu Hause gereinigt werden.","13":"Anzeige g ist ein Elektriker-Notdienst, der rund um die Uhr arbeitet.","14":"Der Malerbetrieb in Anzeige h streicht Wohnungen und macht ein kostenloses Angebot.","15":"Die Schreinerei in Anzeige d repariert unter anderem Türen und Fenster.","16":"Der Second-Hand-Laden in Anzeige i nimmt gut erhaltene Sachen kostenlos an.","17":"Anzeige f bietet Gartenpflege und regelmäßige Betreuung an.","18":"Anzeige e richtet sich an Eigentümer, die die Verwaltung ihrer Wohnung abgeben möchten.","19":"Keine Anzeige bietet eine Ferienwohnung am Meer an; Anzeige e ist nur eine Verwaltung für Eigentümer.","20":"Es gibt keine Anzeige für Computerreparaturen; Anzeige j repariert nur Fahrräder."}'::jsonb, NULL),
    ('telc-deutsch-b1.lv3.02', 'v1', '{"11":"b","12":"c","13":"l","14":"h","15":"g","16":"f","17":"e","18":"j","19":"x","20":"x"}'::jsonb, '{"11":"Anzeige b bietet Krankengymnastik an und verlangt dafür ein Rezept vom Arzt.","12":"Die Apotheke in Anzeige c liefert Medikamente kostenlos nach Hause.","13":"Anzeige l bietet Krankenfahrten zu Untersuchungen und zurück an.","14":"Das Hörgeräte-Zentrum in Anzeige h macht einen kostenlosen Hörtest.","15":"Anzeige g bietet anonyme psychologische Beratung am Telefon an.","16":"Die Ernährungsberatung in Anzeige f erstellt Essenspläne für Familien.","17":"Der Optiker in Anzeige e fertigt Brillen innerhalb einer Stunde an.","18":"Der Pflegedienst in Anzeige j hilft zu Hause bei der Körperpflege.","19":"Keine Anzeige bietet Autos oder Probefahrten an; Anzeige l bietet nur Fahrten zum Arzt.","20":"Für Küchen und Einbau gibt es in diesen Anzeigen kein Angebot; es geht hier nur um Gesundheit."}'::jsonb, NULL),
    ('telc-deutsch-b1.lv3.03', 'v1', '{"11":"b","12":"c","13":"i","14":"e","15":"d","16":"h","17":"j","18":"g","19":"x","20":"x"}'::jsonb, '{"11":"Anzeige b bietet einen Flughafentransfer mit Abholung zu Hause an, auch nachts.","12":"Der Fahrradverleih in Anzeige c hat Räder für Erwachsene und Kinder.","13":"Anzeige i bietet Schließfächer im Hauptbahnhof an.","14":"Der Fernbus in Anzeige e fährt täglich Berlin–Hamburg schon ab 9 Euro.","15":"Anzeige d bietet Sprachreisen für Jugendliche mit Gastfamilie und Unterricht an.","16":"Das Wohnmobil in Anzeige h bietet Platz für vier Personen.","17":"Anzeige j bietet zweistündige Stadtführungen zu Fuß an, ohne Anmeldung.","18":"Die Autovermietung in Anzeige g vermietet Kleinwagen pro Tag mit unbegrenzten Kilometern.","19":"Keine Anzeige verkauft Baumaterial; alle Angebote betreffen Reisen und Verkehr.","20":"Eine Putzhilfe wird in keiner der Anzeigen angeboten."}'::jsonb, NULL),
    ('telc-deutsch-b1.sb1.01', 'v1', '{"21":"b","22":"a","23":"a","24":"a","25":"a","26":"a","27":"a","28":"a","29":"a","30":"a"}'::jsonb, '{"21":"Bei „ankommen“ bildet man das Perfekt mit „sein“: Wir sind angekommen.","22":"Der Gegensatz wird mit dem Adverb „trotzdem“ ausgedrückt, danach folgt das Verb.","23":"„liegen“ steht mit dem Dativ: direkt am Meer.","24":"Nach „haben“ steht der Akkusativ maskulin: einen ruhigen Strand.","25":"Das Relativpronomen bezieht sich auf „ein kleines Dorf“ und ist Subjekt: das.","26":"Im Perfekt steht das Partizip II: Ich habe verloren.","27":"„fragen“ verlangt den Akkusativ: Kannst du deinen Bruder fragen?","28":"„sich freuen auf“ steht mit dem Akkusativ, deshalb „auf sie“.","29":"Der Vergleich mit „als“ verlangt den Komparativ: viel wärmer als zu Hause.","30":"Der irreale Wunsch steht im Konjunktiv II: Es wäre schön."}'::jsonb, NULL),
    ('telc-deutsch-b1.sb1.02', 'v1', '{"21":"a","22":"a","23":"a","24":"a","25":"a","26":"a","27":"a","28":"a","29":"a","30":"a"}'::jsonb, '{"21":"Ein abgeschlossener Zeitpunkt in der Vergangenheit braucht „vor“: Vor drei Wochen bin ich umgezogen.","22":"Nach „viel“ und vor „als“ steht der Komparativ: viel größer als meine alte.","23":"Das Subjekt ist „du“, deshalb lautet die Form „kannst“.","24":"Bezugswort ist „die Frau“; das Relativpronomen ist Subjekt und heißt „die“.","25":"„einladen“ steht mit dem Akkusativ, die Nachbarin ist „sie“.","26":"Bei „auspacken“ steht das Verb an zweiter Stelle und die Vorsilbe „aus“ am Satzende.","27":"„aufbauen“ bildet das Perfekt mit „haben“: Ich habe aufgebaut.","28":"Nach „einen“ steht im Akkusativ maskulin die Endung -en: einen großen Park.","29":"Wenn man sich auf etwas Zukünftiges freut, sagt man „sich freuen auf“ + Akkusativ.","30":"Nach „Schreib mir bitte“ ist es eine indirekte Frage, deshalb „ob“."}'::jsonb, NULL),
    ('telc-deutsch-b1.sb1.03', 'v1', '{"21":"a","22":"a","23":"a","24":"a","25":"a","26":"a","27":"a","28":"a","29":"a","30":"a"}'::jsonb, '{"21":"Für die Zukunft ab einem Zeitpunkt verwendet man „ab“: Ab Montag arbeite ich dort.","22":"Hier steht ein Gegensatz: besser bezahlt, obwohl ich weniger Freizeit habe.","23":"Nach „eine“ im Nominativ feminin steht die Endung -e: eine nette Frau.","24":"Das Relativpronomen ist Objekt im Akkusativ Plural: die Kollegen, die ich kenne.","25":"„finden“ verlangt den Akkusativ: ich habe meinen Computer nicht gefunden.","26":"Man spricht „mit“ jemandem: mit Kunden sprechen.","27":"Eine höfliche Bitte formuliert man mit dem Konjunktiv II: Könntest du mir helfen?","28":"„unterschreiben“ bildet das Perfekt mit „haben“: Ich habe unterschrieben.","29":"Das Subjekt ist „ich“, deshalb heißt die Form „möchte“.","30":"Der Vergleich mit „als“ verlangt den Komparativ: viel freundlicher als der alte."}'::jsonb, NULL),
    ('telc-deutsch-b1.sb2.01', 'v1', '{"31":"a","32":"b","33":"c","34":"d","35":"e","36":"f","37":"g","38":"h","39":"i","40":"j"}'::jsonb, '{"31":"„Deshalb“ leitet die Folge ein und steht auf Position 1, danach kommt das Verb.","32":"„ziehen“ (Umzug) bildet das Perfekt mit „sein“: Ich bin gezogen.","33":"Der Gegensatz im Nebensatz verlangt „obwohl“.","34":"„Da“ leitet einen kausalen Nebensatz ein, der vor dem Hauptsatz steht.","35":"Eine höfliche Frage bildet man mit dem Konjunktiv II: Könnten Sie …?","36":"„gehören“ steht mit dem Dativ: meiner Schwester.","37":"„Während“ + Genitiv: Während meines Urlaubs.","38":"Das Subjekt ist „ich“, deshalb „muss“: Ich muss den Vertrag übersetzen lassen.","39":"Der Gegensatz zwischen dem Anrufen und der fehlenden Antwort verlangt „trotzdem“.","40":"„schicken“ steht mit dem Dativ: Bitte schicken Sie mir eine Bestätigung."}'::jsonb, NULL),
    ('telc-deutsch-b1.sb2.02', 'v1', '{"31":"a","32":"b","33":"c","34":"d","35":"e","36":"f","37":"g","38":"h","39":"i","40":"j"}'::jsonb, '{"31":"„wegen“ + Genitiv: Wegen Ihrer Anzeige bewerbe ich mich.","32":"Man studiert „an“ einer Universität: an der Universität Köln.","33":"„Da“ leitet den kausalen Nebensatz ein, danach folgt der Hauptsatz.","34":"Im Nebenjob ist die Vergangenheit von „können“ gemeint: konnte ich Kunden beraten.","35":"Das trennbare Verb „mitteilen“ steht hier mit der Vorsilbe „mit“ am Satzende: Teilen Sie mir bitte mit.","36":"Höfliche Form im Hauptsatz: Ich würde mich sehr freuen.","37":"„während“ + Genitiv: Während meines Studiums.","38":"Der Vergleich mit „als“ verlangt den Komparativ: besser als in Englisch.","39":"Höfliche Bitte mit dem Konjunktiv II: Könnten Sie bitte …?","40":"„senden“ steht mit dem Dativ: Bitte senden Sie mir eine Antwort."}'::jsonb, NULL),
    ('telc-deutsch-b1.sb2.03', 'v1', '{"31":"a","32":"b","33":"c","34":"d","35":"e","36":"f","37":"g","38":"h","39":"i","40":"j"}'::jsonb, '{"31":"„erfahren“ steht mit „auf“ + Dativ: Auf Ihrer Internetseite habe ich erfahren.","32":"Höfliche Absicht im Konjunktiv II: Ich würde mich gern anmelden.","33":"„Da“ leitet den kausalen Nebensatz ein, der vor dem Hauptsatz steht.","34":"Der Gegensatz verlangt das Adverb „trotzdem“ mit Verb an zweiter Stelle.","35":"Höfliche Frage mit dem Konjunktiv II: Könnten Sie mir mitteilen …?","36":"Die Zeitspanne wird mit „von … bis“ angegeben: von Montag bis Freitag.","37":"Eine Bedingung leitet man mit „wenn“ ein: Wenn der Kurs am Wochenende stattfindet, …","38":"Der Vergleich mit „als“ verlangt den Komparativ: besser als andere Kurse.","39":"„schicken“ steht mit dem Dativ: Bitte schicken Sie mir Informationen.","40":"„lesen“ bildet das Perfekt mit „haben“: Ich habe die AGB gelesen."}'::jsonb, NULL)
    ON CONFLICT (set_id, version) DO NOTHING;

    REVOKE ALL ON "__SCHEMA__".objective_key FROM PUBLIC;
    REVOKE ALL ON "__SCHEMA__".objective_key FROM __LEARNER__;
    GRANT SELECT ON "__SCHEMA__".objective_key TO __WORKER__;

    REVOKE ALL ON "__SCHEMA__".objective_set FROM PUBLIC;
